message.content:
{
  "description": "The creature is a quadruped shown in right-facing profile standing on a small patch of sandy, pebbly ground. It has the overall size, posture, fur, head, hind limbs and tail of a gray wolf, but its back, neck and crown are covered by a dark, glossy, segmented crustacean-like carapace, and its two front limbs end not in paws but in large, dark crab-like pincers that rest on the ground. The fur is dense and shaggy, gray with lighter underparts, and the shell is blackish-gray with overlapping segments and scalloped, slightly spiky edges.",
  "parts": [
    {
      "part": "head",
      "looks_like": "a wolf's head with a long pointed muzzle, black nose, yellow-brown eyes, and gray and white fur, facing to the right",
      "where": "at the front end of the body, connected to the neck"
    },
    {
      "part": "ears",
      "looks_like": "two upright, pointed, triangular ears covered in gray fur with pinkish inner fur",
      "where": "on top of the head, protruding through a dark plate that caps the crown"
    },
    {
      "part": "legs",
      "looks_like": "four furry legs; the two hind legs are slender and wolf-like with bent hocks, the two front legs are thicker and straighter and end in pincers",
      "where": "under the body, two in front under the chest and two in back under the hips, supporting the body in a standing pose"
    },
    {
      "part": "feet",
      "looks_like": "hind feet are wolf paws with toes, dark nails and pads; front feet are large, glossy, dark gray-black chelae with two curved, pointed pincers each and small bumpy textures at the base where they join the fur",
      "where": "at the bottom of each leg; hind paws on the ground at the rear, front pincers touching the ground at the front"
    },
    {
      "part": "tail",
      "looks_like": "a long, thick, bushy tail covered in long gray and dark gray fur, tapering slightly toward the tip",
      "where": "at the rear of the body, extending down and slightly outward from the base of the back"
    },
    {
      "part": "shell",
      "looks_like": "a dark gray to black, glossy, hard-looking segmented carapace with overlapping sections and a scalloped, slightly spiny lower margin",
      "where": "covering the dorsal surface from the top of the head, over the back of the neck, and along the entire back to just above the tail base, sitting on top of the fur"
    },
    {
      "part": "plates",
      "looks_like": "individual overlapping transverse plates that make up the shell; the back plates are broad and smooth with ridged lines, the neck plates form a ruffled collar around the neck, and the head plate is a small cap with a wavy edge and two small rivet-like bumps at the front",
      "where": "as part of the shell: largest plates over the mid-back and shoulders, smaller collar-like plates around the neck, and a cap-like plate on the crown between the ears"
    },
    {
      "part": "markings",
      "looks_like": "dense shaggy fur that is medium to dark gray on the back, sides, head and tail, and much lighter whitish-gray on the muzzle, throat, chest, belly and inner legs, with natural shading and no distinct spots or stripes",
      "where": "covering the entire body except where the shell covers the back and head"
    }
  ],
  "attached_objects": [],
  "animals": [
    "wolf",
    "crab"
  ],
  "separate_bodies": 1,
  "heads": 1,
  "walking_legs": 4,
  "wings": 0,
  "extra_limb_pieces": 0,
  "tails": 1
}
